import sys


def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    k = int(input_data[1])

    freq = {0: 1}
    current_sum = 0
    ans = 0

    for i in range(2, 2 + n):
        current_sum += int(input_data[i])
        target = current_sum - k
        if target in freq:
            ans += freq[target]

        freq[current_sum] = freq.get(current_sum, 0) + 1

    print(ans)


if __name__ == "__main__":
    main()
